/* Career Glitch — step details, wave 3 (truck driver).
   Guard pattern (same as details4.js): STEP_DETAILS may already
   exist from details1-4.js; assign into it, never replace it. */
var STEP_DETAILS = (typeof STEP_DETAILS !== "undefined" && STEP_DETAILS) || {};
/* --- TRUCK DRIVER step details (trk-g1..trk-k4) ---
   Links verified by fetching on Nov 1, 2026 (package spec §8 audit):
   BLS OOH, FMCSA registry/CDL pages, Clearinghouse, TSA. */
Object.assign(STEP_DETAILS, {
'trk-g1': {
  what: 'Before you spend money, choose which job you are training for. The title "truck driver" covers six jobs: long-haul OTR (over-the-road — weeks away from home), regional, local/LTL city (small mixed loads), tanker & hazmat, flatbed/heavy haul/car haul, or owner-operator.',
  whatRu: 'Прежде чем тратить деньги, выберите, на какую работу вы учитесь. За названием «водитель грузовика» — шесть работ: дальние рейсы OTR (over-the-road — недели вне дома), региональные, городские LTL (сборные грузы), цистерны и опасные грузы, платформы/тяжёлые перевозки/автовозы или свой грузовик.',
  how: ['Read the six verdicts on your result screen. Each job has its own verdict and timeline', 'Write your target job in one sentence, with home time in it ("local, home daily")', 'Check now what this job asks for: years of experience and endorsement letters (extra marks on your licence)', 'Check every later step against this sentence'],
  howRu: ['Прочитайте шесть вердиктов на экране результата. У каждой работы свой вердикт и свои сроки', 'Напишите одним предложением, какую работу хотите и как часто будете дома («город, дома каждую ночь»)', 'Сразу проверьте, что требуют на этой работе: сколько лет опыта и какие буквы-допуски (отметки в правах)', 'Каждый следующий шаг сверяйте с этим предложением'],
  why: 'The license is the same for all six jobs. The careers are not. We checked 37 live job posts. Pay goes from $960 a week (long-haul van) to $120,000+ a year (car haul). If you wait, the first carrier picks for you. And carriers mostly push long-haul jobs.',
  whyRu: 'Права одинаковые для всех шести работ. А карьеры — разные. Мы смотрели 37 живых вакансий. Платят от 960 долларов в неделю (дальний фургон) до 120 000+ долларов в год (автовоз). Если тянуть, за вас выберет первый перевозчик. А перевозчики чаще всего зовут на дальние рейсы.',
  links: [{ t: 'BLS — Heavy and Tractor-Trailer Truck Drivers (pay, outlook, what they do)', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-g2': {
  what: 'Since February 2022, federal rules (ELDT, training for new drivers) say this. Your training counts only if the school is in the Training Provider Registry of FMCSA (the US trucking safety agency). Check the exact school and address there before you pay.',
  whatRu: 'С февраля 2022 года действуют федеральные правила ELDT (обязательная подготовка новых водителей). Обучение засчитывается, только если школа есть в реестре FMCSA (агентство США по безопасности грузоперевозок). Проверьте там точную школу и адрес до любой оплаты.',
  how: ['Open the registry (link below) and search the school by name and state', 'Check the exact address where you\'ll study — chains list each site separately', 'Look for the status "active". 9,985 locations have been removed from the registry so far', 'Check again the week training starts. Schools get removed mid-course too'],
  howRu: ['Откройте реестр (ссылка ниже) и найдите школу по названию и штату', 'Проверьте точный адрес, где будете учиться: у сетей каждая точка в списке отдельно', 'Смотрите статус: «активна». Из реестра уже удалили 9 985 точек', 'Проверьте ещё раз в неделю начала учёбы: школы удаляют и посреди курса'],
  why: 'If the school gets removed, your training may stop counting. Even after you paid. The good news: the registry is free and takes two minutes. It\'s the cheapest protection on this whole path.',
  whyRu: 'Если школу удалят, обучение может перестать засчитываться. Даже если вы уже заплатили. Хорошая новость: реестр бесплатный и занимает две минуты. Это самая дешёвая страховка на всём пути.',
  links: [{ t: 'FMCSA — Training Provider Registry (check your school)', u: 'https://tpr.fmcsa.dot.gov/' }]
},
'trk-g3': {
  what: 'Two paper checks come before the license. First, a DOT medical card: a certified doctor checks you can drive safely. Second, your own record: the FMCSA Clearinghouse (drug & alcohol violations) and your state driving record (MVR).',
  whatRu: 'До прав нужно пройти две бумажные проверки. Первая — медкарта DOT: сертифицированный врач проверяет, что вы можете безопасно водить. Вторая — ваша история: Clearinghouse от FMCSA (база нарушений по алкоголю и наркотикам) и выписка о вождении вашего штата (MVR).',
  how: ['Book the DOT medical exam with a certified doctor. Save the card\'s expiry date in your phone', 'Sign up in the Clearinghouse (link below) before your first hiring check', 'Get your state driving record and read it the way a carrier will', 'Fix errors now. A wrong entry a carrier finds can look like a lie'],
  howRu: ['Запишитесь на медосмотр DOT к сертифицированному врачу. Сохраните срок медкарты в телефоне', 'Зарегистрируйтесь в Clearinghouse (ссылка ниже) до первой проверки при найме', 'Возьмите выписку о вождении в своём штате и прочитайте её глазами перевозчика', 'Исправьте ошибки сейчас. Неверная запись, которую найдёт перевозчик, может выглядеть как ложь'],
  why: 'Every carrier in our 37 job posts runs these checks. LTL job posts say it directly: "no DUI within the last 5 years", "able to obtain a medical card". Know your record before they do. Then there are no surprises.',
  whyRu: 'Все перевозчики из наших 37 вакансий делают эти проверки. Вакансии LTL пишут прямо: «без DUI (вождение в нетрезвом виде) за последние 5 лет», «способность получить медкарту». Узнайте своё досье раньше них. Тогда не будет сюрпризов.',
  links: [{ t: 'FMCSA Clearinghouse — student driver page', u: 'https://clearinghouse.fmcsa.dot.gov/Learn/Student-Driver' }, { t: 'FMCSA — How do I get a commercial driver’s license?', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/how-do-i-get-commercial-drivers-license' }]
},
'trk-g4': {
  what: 'Now the Class A CDL itself (the licence for big trucks), the federal way. First, a learner\'s permit (CLP) after written tests. Then training at a school from the registry. Then a 3-part driving test: pre-trip inspection, basic vehicle control, on-road driving.',
  whatRu: 'Теперь сам CDL класса A (коммерческие права на тяжёлый грузовик с прицепом) по федеральным правилам. Сначала — ученическое разрешение (CLP) после письменных тестов. Потом — обучение в школе из реестра. Потом — экзамен из 3 частей: осмотр перед рейсом, базовое управление, вождение по дороге.',
  how: ['Pass the state written tests and get the CLP. You must be 21 to drive between states', 'Finish ELDT training at a school from the registry (you checked it in the last step)', 'Choose the gearbox on purpose: testing in an automatic adds an "E — no manual" limit to your license', 'In our 37 job posts, automatic trucks are normal and most carriers accept the limit. A few (one car-haul carrier) prefer manual', 'Pass the 3-part driving test. Check your license shows the class and limits you expect'],
  howRu: ['Сдайте письменные тесты штата и получите CLP. Для рейсов между штатами вам должен быть 21 год', 'Пройдите обучение ELDT в школе из реестра (вы проверили её на прошлом шаге)', 'Выберите коробку передач осознанно: экзамен на автомате ставит в права ограничение «E — без механики»', 'В наших 37 вакансиях автомат — норма, и большинство перевозчиков принимают ограничение. Но некоторые (один перевозчик автовозов) хотят механику', 'Сдайте экзамен из 3 частей. Проверьте, что в правах нужные класс и ограничения'],
  why: 'The CDL is a wall that protects this whole job. Because of it, a robot needs new rules and a foreign worker needs a visa to compete with you. Get it clean, with limits you chose yourself. Then every later path stays open.',
  whyRu: 'CDL — это стена, которая защищает всю профессию. Из-за неё роботу нужны новые правила, а иностранцу — виза, чтобы с вами конкурировать. Получите права чисто, с ограничениями, которые выбрали сами. Тогда все следующие пути останутся открытыми.',
  links: [{ t: 'FMCSA — Drivers (classes, endorsements T/N/H/X, the E restriction)', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/drivers' }, { t: 'FMCSA — How do I get a commercial driver’s license?', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/how-do-i-get-commercial-drivers-license' }]
},
'trk-g5': {
  what: 'How to pay. Option one: a private or community-college school (about $3,000–$10,000, you pay, no strings). Option two: a carrier\'s "free" school. The carrier pays, but you sign a work contract. Leave early and you get a bill — commonly $3,000–$7,000.',
  whatRu: 'Как платить. Вариант первый: частная школа или колледж (около 3 000–10 000 долларов, платите вы, без обязательств). Вариант второй: «бесплатная» школа перевозчика. Платит перевозчик, но вы подписываете рабочий контракт. Уйдёте раньше — получите счёт, обычно 3 000–7 000 долларов.',
  how: ['Write down the price of both options, for equally good schools from the registry', 'If a carrier pays, get in writing before you sign: contract length, payback amount, what happens if THEY fire you', 'Compare the payback bill with the pay difference. A contract that keeps you in the worst-paid job can cost more than school', 'Never let the way you pay pick your job. You already chose the job in step 1'],
  howRu: ['Запишите цену обоих вариантов для одинаково хороших школ из реестра', 'Если платит перевозчик, до подписи получите письменно: срок контракта, сумму возврата и что будет, если уволят ВАС', 'Сравните сумму возврата с разницей в зарплате. Контракт, который держит вас на самой низкооплачиваемой работе, может стоить дороже учёбы', 'Не позволяйте способу оплаты выбирать вам работу. Работу вы уже выбрали на шаге 1'],
  why: 'The school bill is the price of a mistake here. $3,000–$10,000 spent on the one risky job is the costly way in. Pay yourself, and you\'re free to leave at month 12. With a contract you get the same license, but you\'re stuck.',
  whyRu: 'Счёт за школу — это цена ошибки в этой профессии. 3 000–10 000 долларов, потраченные на единственную рискованную работу, — самый дорогой путь. Платите сами — и сможете уйти на 12-й месяц. С контрактом права те же, но уйти нельзя.',
  links: [{ t: 'FMCSA — Training Provider Registry (compare listed schools before pricing)', u: 'https://tpr.fmcsa.dot.gov/' }]
},
'trk-p1': {
  what: 'See your first driving job in a new way. Its real prize is not the paycheck. It\'s 12 clean months on your record. The YES jobs here (LTL city, tanker, car haul) ask for 1–2 years of experience.',
  whatRu: 'Посмотрите на первую работу водителем по-новому. Главное в ней — не зарплата. Главное — 12 чистых месяцев в вашей истории. Работы с вердиктом ДА (городской LTL, цистерны, автовозы) просят 1–2 года опыта.',
  how: ['Take a first job you can stick with. 13 of 37 job posts hire new CDL holders — mostly long-haul and team driving', 'Write down your move date (month 12) now, while the job is new', 'One rule for the year: no avoidable accident. That\'s worth more than any sign-on bonus', 'Compare your weekly pay with posted pay for your job type. Two months in a row below that is a sign, not bad luck'],
  howRu: ['Берите первую работу, на которой сможете продержаться. 13 из 37 вакансий берут новичков с CDL — в основном дальние рейсы и работа в паре', 'Запишите дату перехода (12-й месяц) сейчас, пока работа новая', 'Одно правило на год: ни одной аварии по вашей вине. Это дороже любого бонуса за выход', 'Сравнивайте свою недельную оплату с тем, сколько платят на вашей работе по вакансиям. Два месяца подряд ниже — это сигнал, а не невезение'],
  why: 'The first year is hard for many drivers. Big long-haul carriers have lost about 94% of drivers a year. The ones who reach good jobs aren\'t the toughest. They saw year one as savings with a set end date. You can do that too.',
  whyRu: 'Первый год многим даётся тяжело. Крупные дальнобойные перевозчики теряли около 94% водителей в год. До хороших работ доходят не самые выносливые. А те, кто смотрел на первый год как на вклад с датой снятия. У вас тоже получится.',
  links: [{ t: 'BLS — about 214,500 openings a year, most of them replacements', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-p2': {
  what: 'Endorsements are extra letters on your CDL. Each one is a written test. Hazmat also needs a federal background check. The letters: N (tanker), T (doubles/triples), then H (hazmat). N+H together show as X.',
  whatRu: 'Допуски — это дополнительные буквы в правах CDL. Каждая — письменный тест. Для опасных грузов ещё нужна федеральная проверка биографии. Буквы: N (цистерна), T (двойные/тройные прицепы), потом H (hazmat — опасные грузы). N+H вместе печатаются как X.',
  how: ['Start with N and T: written tests only, no extra school', 'Apply for the hazmat TSA check early — $85.25 (or $41 if you have TWIC). Waiting is the slow part', 'Pass the hazmat written test after TSA approves you', 'Check your license shows the letters; carriers verify them electronically'],
  howRu: ['Начните с N и T: только письменные тесты, отдельная школа не нужна', 'Подайте на проверку TSA для опасных грузов заранее: 85,25 доллара (или 41 доллар, если есть TWIC). Дольше всего — ждать ответа', 'Сдайте тест по опасным грузам, когда TSA вас одобрит', 'Проверьте, что буквы есть в правах: перевозчики проверяют их онлайн'],
  why: 'We counted: hazmat is in 18 of 37 job posts, tanker in 14, doubles/triples in 11. Every LTL job post asks for some or all of them. Three letters can move you from $960 a week to $36 an hour.',
  whyRu: 'Мы посчитали: опасные грузы есть в 18 из 37 вакансий, цистерна — в 14, двойные/тройные прицепы — в 11. Каждая вакансия LTL просит часть этих букв или все. Три буквы — это разница между 960 долларами в неделю и 36 долларами в час.',
  links: [{ t: 'TSA — Hazardous Materials Endorsement (HME)', u: 'https://www.tsa.gov/for-industry/hazmat-endorsement' }, { t: 'FMCSA — Drivers (endorsement codes T / N / H / X)', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/drivers' }]
},
'trk-p3': {
  what: 'The TWIC card (Transportation Worker Identification Credential) is a pass from TSA. It lets you into ports, chemical plants and rail yards without an escort. Some of the best-paid loads are there.',
  whatRu: 'Карта TWIC (удостоверение транспортного работника) — это пропуск от TSA. С ним вы проходите в порты, на химзаводы и ж/д терминалы без сопровождения. Там грузят часть самых дорогих грузов.',
  how: ['Apply online with TSA, then enroll in person with documents (link below)', 'New applicant fee: $124. With TWIC, your hazmat check costs only $41', 'Get it when your target job goes to ports, plants or rail — not before', 'Keep its expiry date next to your medical card date. Drivers get fired over both'],
  howRu: ['Подайте заявку онлайн в TSA, потом придите лично с документами (ссылка ниже)', 'Новый заявитель платит 124 доллара. С TWIC проверка для опасных грузов стоит всего 41 доллар', 'Получайте её, когда ваша работа связана с портами, заводами или железной дорогой. Не раньше', 'Держите её срок рядом со сроком медкарты: из-за просрочки обеих в этой профессии увольняют'],
  why: 'TWIC is in only 3 of 37 job posts. But those are where loads are valuable and guarded — tanker and port work. It\'s a cheap key. Get it when your job starts asking for it.',
  whyRu: 'TWIC есть всего в 3 из 37 вакансий. Но это там, где груз дорогой и охраняемый, — цистерны и порты. Это дешёвый ключ. Получайте его, когда ваша работа начнёт его требовать.',
  links: [{ t: 'TSA — TWIC (Transportation Worker Identification Credential)', u: 'https://www.tsa.gov/for-industry/twic' }]
},
'trk-p4': {
  what: 'Make a clean-record folder (paper or phone). Keep every clean roadside inspection, your Clearinghouse status, medical card, employer letters and any safety awards. Good jobs hire based on this.',
  whatRu: 'Заведите папку чистой истории (бумажную или в телефоне). Храните там каждую чистую проверку на дороге, статус в Clearinghouse, медкарту, письма работодателей и награды за безопасность. На хорошие работы нанимают именно по этому.',
  how: ['Save every inspection report, clean or not — clean ones are gold', 'Photograph documents the day you get them. Paper gets lost in trucks; phones keep a copy', 'Once a year, pull your Clearinghouse and state records and compare them to your file', 'Bring the folder when you apply — LTL and tanker hiring checks exactly this'],
  howRu: ['Сохраняйте каждый акт проверки, чистый или нет. Чистые — на вес золота', 'Фотографируйте документы в день получения. Бумага теряется в кабине, а телефон сохраняет копию', 'Раз в год берите свои записи из Clearinghouse и штата и сверяйте с папкой', 'Берите папку, когда подаётесь: в LTL и цистернах проверяют именно это'],
  why: 'The chief economist of ATA (the US trucking industry group) calls the driver shortage "a quality problem, not a quantity problem". Carriers can\'t find experienced drivers with clean records. Your folder shows you\'re one of them.',
  whyRu: 'Главный экономист ATA (ассоциация грузоперевозчиков США) называет нехватку водителей «проблемой качества, а не количества». Перевозчики не могут найти опытных водителей с чистой историей. Ваша папка показывает, что вы как раз такой.',
  links: [{ t: 'FMCSA Clearinghouse — your record and registration', u: 'https://clearinghouse.fmcsa.dot.gov/Learn/Student-Driver' }]
},
'trk-p5': {
  what: 'Learn one hands-on cargo skill for your target job. Flatbed: tying down loads and covering them with tarps. Tanker: loading, unloading and controlling liquid sloshing. Car haul: loading and moving cars.',
  whatRu: 'Освойте один ручной навык с грузом под вашу работу. Платформа: крепление груза и укрытие брезентом. Цистерна: погрузка, разгрузка и контроль раскачки жидкости. Автовоз: погрузка и перевозка машин.',
  how: ['Pick the skill your target job asks for — read its job posts again', 'Practise it on purpose and photograph your best work (your quest album starts here)', 'Learn to spot problems too: what bad tie-down or loading looks like before you drive', 'Keep proof: photos, trainer sign-offs, any carrier certification'],
  howRu: ['Выберите навык, который требует ваша работа: перечитайте её вакансии', 'Тренируйте его специально и фотографируйте лучшие результаты (здесь начинается ваш альбом для квестов)', 'Научитесь видеть ошибки: как выглядит плохое крепление или погрузка, пока вы не тронулись', 'Храните доказательства: фото, подписи инструкторов, сертификаты перевозчика'],
  why: 'Robots won\'t take this part soon. The BLS job description says drivers "secure the cargo using ropes, chains, or covers" and may load and unload. A robot can drive, but a human still tarps the steel. Be that human, and get paid like a specialist.',
  whyRu: 'Роботы не скоро заберут эту часть. В описании работы BLS сказано: водители «крепят груз верёвками, цепями или укрытиями» и могут грузить и разгружать. Робот может вести, но брезент на сталь натягивает человек. Будьте этим человеком — и получайте как специалист.',
  links: [{ t: 'BLS — What heavy truck drivers do (cargo, loading, inspections)', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-k1': {
  what: 'Time to change jobs: at 12–24 months, with experience and endorsements, apply for the YES job you picked in step 1. That\'s LTL city, tanker, flatbed specialty, car haul or linehaul (long runs between hubs).',
  whatRu: 'Время сменить работу: на 12–24-й месяц, с опытом и допусками, подавайтесь на работу с вердиктом ДА, которую выбрали на шаге 1. Это городской LTL, цистерны, особые грузы на платформах, автовозы или магистральные рейсы.',
  how: ['Apply while you still have a job. These jobs want a working driver with a clean record', 'Add your record folder (last step) and endorsement letters to every application', 'Compare offers by total pay and nights at home. Use your best-week number from the quests', 'Don\'t quit over a spoken promise. Get the written offer and start date first'],
  howRu: ['Подавайтесь, пока ещё работаете. Эти работы ищут работающего водителя с чистой историей', 'Прикладывайте папку истории (прошлый шаг) и буквы-допуски к каждой заявке', 'Сравнивайте предложения по общей оплате и ночам дома. Берите за ориентир свою лучшую неделю из квестов', 'Не увольняйтесь из-за устного обещания. Сначала письменное предложение и дата выхода'],
  why: 'Job posts list the experience they need: 1 year for LTL city, 2 years for car haul, 2 years plus flatbed time for heavy haul. These jobs open at month 12–24. This move is your reward for the first two stages.',
  whyRu: 'Вакансии прямо пишут, какой опыт нужен: 1 год для городского LTL, 2 года для автовозов, 2 года плюс опыт на платформах для тяжёлых перевозок. Эти работы открываются на 12–24-й месяц. Этот переход — ваша награда за два первых этапа.',
  links: [{ t: 'BLS — job outlook: about 214,500 openings per year', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-k2': {
  what: 'Understand how you get paid. The same driving can be paid per mile, as a percent of the load, hourly, or per task (per stop, per trailer move, unloading fees). Turn any plan into one number — dollars per week. Then compare.',
  whatRu: 'Разберитесь, как вам платят. За одно и то же вождение платят по-разному: центы за милю, процент от груза, почасово или за действия (за остановку, перецепку прицепа, разгрузку). Переведите любую схему в одно число — доллары в неделю. Потом сравнивайте.',
  how: ['Take one real pay stub or offer and work out: total pay ÷ weeks, and pay per night away', 'Count what is NOT paid: waiting, loading time, deadhead miles (driving empty)', 'Check when bonuses pay out: sign-on bonuses in our job posts pay over 12 months', 'If a recruiter can\'t show the plan in writing, expect the lowest pay in its range'],
  howRu: ['Возьмите реальный расчётный лист или предложение и посчитайте: общая оплата ÷ недели и оплата за ночь вне дома', 'Посчитайте, что НЕ оплачивается: ожидание, время погрузки, холостые мили (deadhead — пустой пробег)', 'Смотрите, когда платят бонусы: бонусы за выход в наших вакансиях выплачивают в течение 12 месяцев', 'Если рекрутер не может показать схему письменно, рассчитывайте на минимум'],
  why: 'Posted numbers hide the details. One local job post pays $0.68/mile plus $20 per stop plus $50 per trailer move. Is that good or bad? You only know after you add up a real week. Drivers who do the math stop working for free.',
  whyRu: 'Цифры в вакансии скрывают детали. Одна городская вакансия платит 0,68 доллара за милю плюс 20 долларов за остановку плюс 50 долларов за перецепку прицепа. Много это или мало? Видно, только если посчитать реальную неделю. Кто считает, перестаёт работать бесплатно.',
  links: [{ t: 'BLS — pay distribution: bottom 10% under $40,140, top 10% over $79,380', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-k3': {
  what: 'Do the owner-operator math honestly. You get a percent of the load (80–87% in offers we saw). Then subtract fuel, insurance (one carrier lists $298/week), trailer rent if it\'s theirs ($250–$450/week), repairs, taxes and unpaid empty miles.',
  whatRu: 'Честно посчитайте, сколько заработаете на своём грузовике. Вы получаете процент от груза (80–87% в предложениях, которые мы видели). Вычтите топливо, страховку (у одного перевозчика 298 долларов в неделю), аренду их прицепа (250–450 долларов в неделю), ремонт, налоги и неоплаченные пустые мили.',
  how: ['Build the spreadsheet from your own year of company driving (your bill-file quest data)', 'Work out one real week at 80%, 85% and 87%. The percent is what you bargain over', 'Honestly compare it with your company pay for the same week, benefits included', 'Avoid the trap: lease-purchase where the carrier selling you the truck also controls your loads'],
  howRu: ['Соберите таблицу по своему году работы в компании (данные из квеста про расходы)', 'Посчитайте одну реальную неделю при 80%, 85% и 87%. О проценте вы и торгуетесь', 'Честно сравните с оплатой в компании за ту же неделю, включая льготы', 'Избегайте ловушки: лизинг с выкупом, где перевозчик продаёт вам грузовик и сам же даёт грузы'],
  why: 'One carrier\'s own example: $8,000 in a week becomes about $4,500 after costs. Good money, but about half the big number. 161,500 drivers (7.3%) work this way. It\'s a real business, and some do great. The key: do the math before you sign.',
  whyRu: 'Пример самого перевозчика: 8 000 долларов за неделю превращаются примерно в 4 500 после расходов. Хорошие деньги, но почти вдвое меньше громкой цифры. Так работают 161 500 водителей (7,3%). Это настоящий бизнес, и у многих он получается. Главное — посчитать цифры до подписи.',
  links: [{ t: 'BLS — 161,500 of 2,221,200 drivers are self-employed (7%)', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-k4': {
  what: 'Every quarter, check your routes. Compare the routes you really drive with the published self-driving truck routes. Today that\'s Aurora\'s list; Kodiak\'s and Torc\'s when they launch. Also check FMCSA rule changes.',
  whatRu: 'Раз в квартал проверяйте свои маршруты. Сравните трассы, по которым реально ездите, с опубликованными трассами беспилотных грузовиков. Сегодня это список Aurora; Kodiak и Torc — когда запустятся. И следите за изменениями правил FMCSA.',
  how: ['List your three most common lanes, honestly', 'Check each one against the current self-driving route lists in your Radar', 'Note the cargo type: dry van terminal-to-terminal is at risk; hazmat is left out of the federal self-driving rule relief (Oct 2026) for now', 'If your route shows up, start planning your job change. Go back to step k1 with fresh eyes'],
  howRu: ['Честно перечислите три своих самых частых маршрута', 'Сверьте каждый с текущими списками беспилотных трасс в вашем Радаре', 'Отметьте тип груза: сухой фургон от терминала до терминала — под угрозой; опасные грузы пока не входят в федеральные послабления для беспилотных (октябрь 2026)', 'Если ваш маршрут там появился, пора планировать смену работы. Вернитесь к шагу k1 свежим взглядом'],
  why: 'Self-driving trucks arrive route by route, in public. By February 2026 there were five Aurora routes, all Sun Belt interstates (the US South). Check every quarter and you get years of warning. That\'s plenty of time to move.',
  whyRu: 'Беспилотники приходят маршрут за маршрутом, и это всё публично. К февралю 2026 было пять трасс Aurora, все — межштатные трассы на юге США (Солнечный пояс). Проверяйте раз в квартал — и узнаете за годы. Этого хватит, чтобы спокойно перейти.',
  links: [{ t: 'FMCSA — driverless-truck beacon exemption, Oct 7 2026 (hazmat excluded)', u: 'https://www.fmcsa.dot.gov/sites/fmcsa.dot.gov/files/2026-10/Aurora%20Operations%20Exemption_10-07-2026.pdf' }, { t: 'Aurora — 250,000 driverless miles, the lane list (Feb 11, 2026)', u: 'https://www.businesswire.com/news/home/20260211346263/en/Aurora-Triples-Driverless-Network-to-10-Routes-and-Prepares-to-Expand-Across-U.S.-Sun-Belt' }]
}
});

/* --- MENTAL HEALTH COUNSELOR step details (cns-g1..cns-k4) ---
   Links: only URLs returned verbatim by search/fetch on Nov 1, 2026
   (BLS, NBCC, IDFPR, Arizona board, per package spec §8). */
Object.assign(STEP_DETAILS, {
'cns-g1': {
  what:'First, pick which of five jobs you\'re aiming for. Do it before you spend any money. Good choices: a licensed group or private practice, or a community agency. Two to avoid as final stops: app-based gig work and the certificate-only path.',
  how:['Read the five rows on your result card one more time.','Write the one job you\'re aiming for, in one line.','Under it, write the two NO jobs. Now you know what to skip.'],
  why:'We looked at 44 job posts. One title hides five very different pay levels. The bottom pays $43 an hour. The top pays $135,000 a year. The job you aim for decides which you get.',
  whatRu:'Сначала выберите, к какой из пяти работ вы идёте. Сделайте это до любых трат. Хорошие варианты: своя или групповая практика с лицензией или общественное агентство. Два варианта лучше не делать конечной целью: подработка через приложение и путь только с сертификатом.',
  howRu:['Ещё раз прочитайте пять строк в карточке результата.','Запишите одной строкой работу, к которой идёте.','Под ней запишите две работы NO. Так понятно, чего избегать.'],
  whyRu:'Мы посмотрели 44 вакансии. За одним названием — пять очень разных зарплат. Внизу платят $43 в час. Наверху — $135,000 в год. Какую получите вы, решает работа, к которой вы идёте.',
  links:[{t:'BLS — Substance Abuse, Behavioral Disorder & Mental Health Counselors (official pay and outlook)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-g2': {
  what:'Choose a 60-credit master\'s in counseling. Your state board (the group that gives licences) must accept it. CACREP (the national group that checks counseling programs) is the safest pick. A few states require a CACREP degree.',
  how:['Open your state board\'s page on what schooling you need for the counselor licence.','Check how many credits it asks for (usually 60) and whether CACREP is required or just OK.','Compare your program with that page, in writing, before your next tuition payment.','If the program is not CACREP and the board doesn\'t count it as equal, stop and rethink. This really matters.'],
  why:'The wrong degree is the most costly mistake here. A master\'s can cost $40,000–$100,000 or more. If the board doesn\'t accept it, you get no licence. Employers check this. Thriveworks asks for “a graduate of an approved 60-credit hour program.” Check early, and you\'re safe.',
  whatRu:'Выберите магистратуру по консультированию на 60 кредитов (учебных единиц). Её должен принимать совет вашего штата (board) — те, кто выдаёт лицензии. Самый надёжный вариант — программа с CACREP (национальная проверка программ). Некоторые штаты требуют именно CACREP.',
  howRu:['Откройте на сайте совета вашего штата, какое образование нужно для лицензии консультанта.','Посмотрите, сколько кредитов нужно (обычно 60) и нужен ли CACREP или он просто подходит.','Сверьте свою программу с этой страницей, письменно, до следующей оплаты учёбы.','Если программа не CACREP и совет не считает её равной — остановитесь и подумайте. Это очень важно.'],
  whyRu:'Неправильный диплом — самая дорогая ошибка здесь. Магистратура стоит $40,000–$100,000 и больше. Если совет её не примет, лицензии не будет. Работодатели это проверяют. Thriveworks пишет: «выпускник одобренной программы на 60 кредитов». Проверьте заранее — и всё будет хорошо.',
  links:[{t:'BLS — how this occupation is entered (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'},
         {t:'NBCC — National Certified Counselor eligibility (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-g3': {
  what:'Pass the licence exam your state board names. It\'s either the NCE (200 multiple-choice questions) or the NCMHCE (practice with made-up client cases). NBCC (the national counselors\' board) runs both.',
  how:['On your state board\'s page, find which exam it accepts. Many states take either one.','Sign up through NBCC when your board says you can. Some states let you take it during your supervised years.','Study for the exam you\'ll really take: questions for the NCE, client cases for the NCMHCE.','Keep your passing score report with your licence papers.'],
  why:'No exam, no licence. And 30 of 44 job posts need the full licence. NBCC uses the same two exams for its own certificate.',
  whatRu:'Сдайте экзамен на лицензию, который называет совет вашего штата. Это NCE (200 вопросов с вариантами ответа) или NCMHCE (разбор придуманных случаев с клиентами). Оба проводит NBCC — национальный совет консультантов.',
  howRu:['Найдите на сайте совета вашего штата, какой экзамен он принимает. Многие штаты — любой из двух.','Запишитесь через NBCC, когда совет разрешит. В некоторых штатах можно сдавать в годы под супервизией (работы под присмотром опытного коллеги).','Готовьтесь к тому экзамену, который будете сдавать: вопросы для NCE, случаи с клиентами для NCMHCE.','Храните результат экзамена вместе с документами на лицензию.'],
  whyRu:'Без экзамена нет лицензии. А 30 из 44 вакансий требуют полную лицензию. NBCC использует те же два экзамена для своего сертификата.',
  links:[{t:'NBCC — NCC eligibility: the NCE / NCMHCE requirement (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-g4': {
  what:'Plan your supervised years like a project, before they start. Supervised means you work while an experienced, licensed counselor guides you. Write down: your state\'s hour total (2,000–3,000 hours in the states we checked), your approved supervisor, and where the hours will come from.',
  how:['Write your state’s exact hour number at the top of the plan (state examples: Connecticut 3,000 + 100 supervision hours; Texas 3,000; Illinois 3,360; Florida 1,500 face-to-face hours over at least 100 weeks).','Find out which supervisor your board approves. Usually it\'s a licensed counselor (or other licensed clinician) who is allowed to supervise.','Split the hours over months. At 25 client sessions a week (the usual load in job posts), it takes about two years.','Decide now: will your employer give you supervision, or will you pay for it? That\'s the next step, cns-g5.'],
  why:'This is where many plans quietly get stuck — not the degree. Beginners earn $40,000–$65,000 here. Hours without an approved supervisor don\'t count at all. Plan it well, and you\'ll get through.',
  whatRu:'Спланируйте годы под супервизией как проект, ещё до старта. Супервизия — это когда вы работаете, а опытный лицензированный коллега вас направляет. Запишите: сколько часов нужно в вашем штате (от 2,000 до 3,000 часов в штатах, которые мы смотрели), кто ваш одобренный советом супервизор и откуда возьмутся часы.',
  howRu:['Запишите точное число часов вашего штата в начале плана (примеры: Коннектикут — 3,000 + 100 часов супервизии; Техас — 3,000; Иллинойс — 3,360; Флорида — 1,500 часов вживую с клиентами минимум за 100 недель).','Узнайте, какого супервизора одобряет ваш совет. Обычно это лицензированный консультант (или другой лицензированный специалист), которому можно вести супервизию.','Разделите часы на месяцы. При 25 сессиях с клиентами в неделю (обычная нагрузка в вакансиях) выходит около двух лет.','Решите сейчас: супервизию даст работодатель или вы оплатите её сами? Это следующий шаг, cns-g5.'],
  whyRu:'Именно здесь многие планы тихо застревают — а не на дипломе. Новичкам здесь платят $40,000–$65,000. Часы без одобренного супервизора не засчитываются совсем. Спланируйте заранее — и вы пройдёте.',
  links:[{t:'NBCC — supervised experience standard: 3,000 hours + 100 supervision hours (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-g5': {
  what:'Before you say yes to a beginner (associate) job, get the supervision deal in writing. Who supervises you? Does the board approve them? How often do you meet? Who pays?',
  how:['Ask the question in the interview, in these words: “Who is my clinical supervisor, and is the supervision board-approved toward licensure?”','Ask if supervision is one-on-one, in a group, or both, and how hours get recorded.','If they don\'t give supervision, find out what a private approved supervisor costs before saying yes. That money comes out of your salary.','Get the answer into your offer letter. A spoken promise from a recruiter doesn\'t count.'],
  why:'Ten job posts offer free supervision, in writing (Thriveworks, Ellie Mental Health, Helio Health, GearingUp, Daybreak Health). Where it\'s not offered, the beginner pays for it from a $40,000–$65,000 salary — for two years. So ask. It\'s a normal question.',
  whatRu:'Прежде чем согласиться на работу новичка (associate), получите условия супервизии письменно. Кто ваш супервизор? Одобрил ли его совет (board)? Как часто вы встречаетесь? Кто платит?',
  howRu:['Задайте вопрос на собеседовании этими словами: «Кто мой клинический супервизор, и одобрена ли супервизия советом в счёт лицензии?»','Спросите, супервизия один на один, в группе или и так, и так, и как записываются часы.','Если супервизию не дают, до согласия узнайте, сколько стоит частный одобренный супервизор. Эти деньги уйдут из вашей зарплаты.','Попросите вписать это в письмо с предложением работы. Устное обещание рекрутера не считается.'],
  whyRu:'Десять вакансий дают супервизию бесплатно и письменно (Thriveworks, Ellie Mental Health, Helio Health, GearingUp, Daybreak Health). Где её нет, новичок платит за неё сам из зарплаты $40,000–$65,000 — два года. Так что спрашивайте. Это нормальный вопрос.',
  links:[{t:'BLS — pay and outlook for this occupation (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-p1': {
  what:'Finish the practice hours inside your degree: 100 practicum hours and 600 internship hours. That\'s real places, real clients, with a supervisor guiding you.',
  how:['Pick internship places that match the job you want. A group practice or agency is better than a place unrelated to your plan.','Write down your hours every week from week one — in the program\'s system and in your own copy.','Ask each supervisor there for one written review per term, and keep it.','Treat your internship like your first job interview. Places in our search hire their own interns.'],
  why:'These 700 hours are the base of your licence papers. They\'re also the first experience employers look at. And it\'s the only time supervision comes free with your school.',
  whatRu:'Отработайте часы практики во время учёбы: 100 часов практикума и 600 часов интернатуры. Это настоящие места, настоящие клиенты и супервизор рядом.',
  howRu:['Выбирайте места интернатуры под работу, которую хотите. Групповая практика или агентство лучше, чем место, не связанное с вашим планом.','Записывайте часы каждую неделю с самой первой — в системе программы и в своей копии.','Просите у каждого супервизора на месте один письменный отзыв за семестр и храните его.','Считайте интернатуру первым собеседованием. Места из нашего поиска берут своих интернов на работу.'],
  whyRu:'Эти 700 часов — основа ваших документов на лицензию. И первый опыт, который смотрят работодатели. Это ещё и единственное время, когда супервизия бесплатно входит в учёбу.',
  links:[{t:'NBCC — education and examination standards (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-p2': {
  what:'Write down every supervised hour, every week, in two places: your employer\'s system and your own copy. Note the date, the hours, the type of client contact, and the supervision you got.',
  how:['Set a 10-minute weekly date with yourself to log hours.','Write client hours and total hours separately. Boards count them differently.','Have your supervisor sign or confirm the log regularly, not at year\'s end.','Keep the file after you leave the job. Boards can check old logs.'],
  why:'Hours you don\'t write down don\'t count. That\'s true in every state. If you log weekly, you finish the 2,000–3,000 hours on time. If you try to remember them all at the end, you lose months. A little each week keeps you safe.',
  whatRu:'Записывайте каждый час под супервизией, каждую неделю, в двух местах: в системе работодателя и в своей копии. Отмечайте дату, часы, вид работы с клиентом и полученную супервизию.',
  howRu:['Назначьте себе 10 минут в неделю на запись часов.','Записывайте часы с клиентами и общие часы отдельно. Советы (boards) считают их по-разному.','Пусть супервизор подписывает или подтверждает журнал регулярно, а не в конце года.','Храните файл и после ухода с работы. Советы могут проверить старые записи.'],
  whyRu:'Часы, которые не записаны, не считаются. Так во всех штатах. Кто записывает каждую неделю, проходит от 2,000 до 3,000 часов вовремя. Кто пытается вспомнить всё в конце, теряет месяцы. Понемногу каждую неделю — и вы в безопасности.',
  links:[{t:'NBCC — documented, supervised experience requirement (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-p3': {
  what:'Train for real in one named method employers print in postings: CBT (cognitive behavioral therapy), DBT (dialectical behavior therapy), EMDR (trauma work), or motivational interviewing.',
  how:['Look at 10 job posts for the job you want. Count which method names show up. Learn the one that repeats most.','Choose a real course with practice and feedback, not a one-hour webinar.','Try the method first with clients your supervisor watches over, and tell them about it.','Write the full method name on your resume. Job posts look for these exact words.'],
  why:'No job post asks for a “good listener”. They ask for named methods. Changing Paths NC lists CBT, DBT and motivational interviewing. A named specialty moves you from general work to $75,000–$135,000 practice pay.',
  whatRu:'Хорошо освойте один известный метод, который просят в вакансиях: CBT (когнитивно-поведенческая терапия), DBT (диалектическая поведенческая терапия), EMDR (работа с травмой) или мотивационное интервью.',
  howRu:['Посмотрите 10 вакансий на работу, которую хотите. Посчитайте, какие методы там названы. Учите тот, что встречается чаще.','Выберите настоящее обучение с практикой и разбором, а не часовой вебинар.','Сначала пробуйте метод с клиентами под супервизией и рассказывайте об этом супервизору.','Напишите полное название метода в резюме. Вакансии ищут именно эти слова.'],
  whyRu:'Ни одна вакансия не просит «хорошего слушателя». Просят методы по названию. Changing Paths NC прямо пишет CBT, DBT и мотивационное интервью. Специальность с названием переводит вас от общей работы к зарплатам практики $75,000–$135,000.',
  links:[{t:'BLS — what employers and settings look like for this occupation (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-p4': {
  what:'Learn the computer system for client notes your employer uses. Our search found Epic, Netsmart Avatar and AthenaOne. Build a habit of quick, tidy notes. Use AI note tools only where your employer and state allow it.',
  how:['In the interview, ask which notes system they use. Write it down.','Learn the system’s note templates in your first month, not your sixth.','Time how long your notes take for one week. Make a rule to finish them the same day.','Know your state\'s rule. In Illinois, licensed pros can use AI for helper tasks. Never for therapy decisions or talking with clients.'],
  why:'Notes and paperwork are the part of this job AI is really taking over. Counselors who know the system go home on time. Those who fight it lose their evenings. You can be the first kind.',
  whatRu:'Освойте программу для записей о клиентах, которую использует работодатель. В вакансиях мы нашли Epic, Netsmart Avatar и AthenaOne. Привыкайте делать записи быстро и аккуратно. AI-помощников для записей используйте только там, где разрешают работодатель и штат.',
  howRu:['На собеседовании спросите, в какой программе ведут записи. Запишите.','Освойте шаблоны записей в первый месяц, а не в шестой.','Неделю замеряйте, сколько времени уходит на записи. Поставьте себе правило: заканчивать в тот же день.','Знайте правило своего штата. В Иллинойсе лицензированные специалисты могут использовать AI для вспомогательных задач. Но не для решений о терапии и не для общения с клиентами.'],
  whyRu:'Записи и бумаги — та часть работы, которую AI правда забирает. Кто хорошо знает программу, уходит домой вовремя. Кто с ней воюет, теряет вечера. Вы можете быть из первых.',
  links:[{t:'Illinois IDFPR — the WOPR Act: what AI may and may not do in therapy (official state release)', u:'https://idfpr.illinois.gov/news/2025/gov-pritzker-signs-state-leg-prohibiting-ai-therapy-in-il.html'}]},
'cns-p5': {
  what:'Get ready the papers insurance companies need before they pay for your sessions. That\'s your NPI (national provider number), your CAQH profile (an online file insurers check), and your licence papers. Keep them all in one folder.',
  how:['Get or confirm your NPI number if your job needs one.','Make your CAQH profile and keep its papers up to date. Job posts ask for CAQH by name.','Keep license, diploma, exam score and supervision records as scans in one place.','When you join a practice, ask who handles insurance approval and how long it takes. You can only start paid sessions after that.'],
  why:'If insurers can\'t be billed for you, you can\'t be booked with clients. Daybreak Health\'s job post asks for an active NPI and CAQH by name. Group practices do the same, because insurers set this rule, not employers.',
  whatRu:'Подготовьте бумаги, без которых страховые не платят за ваши сессии. Это NPI (национальный номер специалиста), профиль в CAQH (онлайн-досье, которое смотрят страховые) и документы на лицензию. Держите всё в одной папке.',
  howRu:['Получите номер NPI или проверьте его, если он нужен для вашей работы.','Создайте профиль в CAQH и обновляйте документы. Вакансии прямо просят CAQH.','Храните сканы лицензии, диплома, результата экзамена и записей супервизии в одном месте.','Когда придёте в практику, спросите, кто оформляет вас у страховых и сколько это занимает. Платные сессии начнутся только после этого.'],
  whyRu:'Если страховой нельзя выставить за вас счёт, вас нельзя поставить в расписание. Вакансия Daybreak Health прямо просит действующие NPI и CAQH. Групповые практики делают так же: это правило ставят страховые, а не работодатели.',
  links:[{t:'BLS — work settings and pay by setting (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-k1': {
  what:'Choose where to work by how they pay. Write it down. It\'s a salary, productivity pay (money based on how many clients you see), or pay per live session. Before signing, find out what is NOT paid in each.',
  how:['Take your two best offers. Write how each one pays, in one line.','Under each, list what\'s unpaid: notes, missed sessions, meetings, preparation.','Count a real week: 25 client sessions is a normal full week in beginner job posts. Licensed practice pay assumes about the same.','Pick the pay type whose unpaid parts you can live with — not the biggest number in the ad.'],
  why:'The same licence pays $43 an hour (sessions only, on an app), $68,000–$75,000 (agency salary, 95 billable hours expected) or $75,000–$135,000 (practice, paid per client). How they pay is the real job. The big number is just an ad.',
  whatRu:'Выбирайте место работы по тому, как там платят. Запишите. Это зарплата, оплата за число клиентов (productivity pay) или оплата за каждую живую сессию. До подписи узнайте, что в каждом варианте НЕ оплачивается.',
  howRu:['Возьмите два лучших предложения. Запишите одной строкой, как платят в каждом.','Под каждым перечислите, что не оплачивается: записи, неявки клиентов, совещания, подготовку.','Посчитайте реальную неделю: 25 сессий с клиентами — обычная полная неделя в вакансиях для новичков. В практиках с лицензией — примерно так же.','Выберите вариант, где неоплаченные части вам подходят, — а не самую большую цифру в объявлении.'],
  whyRu:'Одна и та же лицензия даёт $43 в час (только сессии, через приложение), $68,000–$75,000 (зарплата в агентстве, норма 95 оплачиваемых часов) или $75,000–$135,000 (практика, оплата за клиентов). Настоящая работа — это то, как платят. Большая цифра — просто реклама.',
  links:[{t:'BLS — median $59,350 and pay by setting (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-k2': {
  what:'The Counseling Compact is a deal between states. It lets a licensed counselor work in other member states. When your state joins for real, ask for permission to work in the states you want.',
  how:['Check the compact map for two things: is your home state live, and are the states you want live?','Note the gap: 39 states and DC passed the law, but only 11 could give permissions in October 2026.','Apply in the compact\'s system (CompactConnect) for each state separately.','Don\'t see clients in a state where you have no licence or permission. Online sessions follow this rule too.'],
  why:'More states means more pay. One licence opens several states. No second degree, no second round of hours. It only started on 30 September 2025. So if you\'re early, there\'s little competition across state lines.',
  whatRu:'Counseling Compact — это договор между штатами. С ним лицензированный консультант может работать в других штатах договора. Когда ваш штат по-настоящему подключится, подайте на разрешение (privilege to practice) работать в нужных вам штатах.',
  howRu:['Проверьте карту договора: подключён ли ваш штат и подключены ли штаты, которые вам нужны.','Помните разницу: 39 штатов и DC приняли закон, но выдавать разрешения в октябре 2026 года могли только 11.','Подавайте в системе договора (CompactConnect) отдельно на каждый штат.','Не принимайте клиентов в штате, где у вас нет ни лицензии, ни разрешения. Для онлайн-сессий правило то же.'],
  whyRu:'Больше штатов — больше заработок. Одна лицензия открывает несколько штатов. Без второго диплома и второго круга часов. Это заработало только 30 сентября 2025 года. Кто успеет рано, встретит мало конкурентов в других штатах.',
  links:[{t:'Arizona Board of Behavioral Health Examiners — Counseling Compact status (official state board)', u:'https://bbhe.az.gov/counseling-compact'}]},
'cns-k3': {
  what:'Build a circle of people who send you clients. Think psychiatrists, family doctors, school counselors, past supervisors and internship places. They meet your future clients before you do.',
  how:['List 10 names from your training years: supervisors, coworkers, classmates now working elsewhere.','Send two short, clear messages a month: what you help with, who you help most, one open spot.','Thank everyone who sends you a client. With the client\'s OK, share a one-line update.','Track where your last 10 clients came from. That list is your real marketing, not ads.'],
  why:'In private and group practice, no HR team brings you clients. In our search, even big group practices promise “consistent referrals” as a perk. Clients sent by others are hard to find. In your own practice, you bring them in. You can do it, one message at a time.',
  whatRu:'Соберите круг людей, которые будут направлять к вам клиентов. Это психиатры, семейные врачи, школьные психологи, бывшие супервизоры и места интернатуры. Они встречают ваших будущих клиентов раньше вас.',
  howRu:['Запишите 10 имён со времён учёбы: супервизоры, коллеги, одногруппники, которые теперь работают в других местах.','Отправляйте два коротких понятных сообщения в месяц: с чем вы помогаете, кому особенно и одно свободное время.','Благодарите каждого, кто прислал клиента. С согласия клиента одной строкой расскажите, как дела.','Отмечайте, откуда пришли последние 10 клиентов. Этот список — ваш настоящий маркетинг, а не реклама.'],
  whyRu:'В частной и групповой практике никакой отдел кадров не приводит вам клиентов. В нашем поиске даже большие практики обещают «стабильные направления» как бонус. Клиентов по рекомендации найти трудно. В своей практике их приводите вы. У вас получится — по одному сообщению за раз.',
  links:[{t:'BLS — job outlook: +98,000 jobs, about 50,500 openings a year (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-k4': {
  what:'Once a year, check your state and your pay again. Look at its AI-therapy law and its compact status. Compare your pay with new job posts. And ask: is supervisor or clinical lead your next step up?',
  how:['Put a yearly date in your calendar: board rules, compact map, a fresh look at job posts for your job.','Read one radar issue for this job and mark what changed.','If you supervise or could, know it\'s worth money. Job posts list paid supervisor roles (Thriveworks) and use free supervision to attract people. Supervision is a paid skill now.','Change one thing a year: a rate, a specialty, a state permission, or a role. Doing nothing is a choice too, and it has a cost.'],
  why:'Both the rules and the market changed in a single year. Three states passed AI-therapy laws in 2025, and the compact went from law to working. Check once a year, and nothing catches you off guard.',
  whatRu:'Раз в год заново проверяйте свой штат и свою оплату. Посмотрите закон об AI-терапии и подключение к договору штатов. Сравните оплату со свежими вакансиями. И спросите себя: может, следующий шаг — стать супервизором или руководителем?',
  howRu:['Поставьте в календарь дату раз в год: правила совета, карта договора, свежие вакансии на вашу работу.','Прочитайте один выпуск радара по этой профессии и отметьте, что изменилось.','Если вы ведёте супервизию или могли бы — это стоит денег. Вакансии предлагают оплачиваемые роли супервизора (Thriveworks) и бесплатную супервизию, чтобы привлечь людей. Супервизия теперь — оплачиваемый навык.','Меняйте одну вещь в год: ставку, специальность, разрешение штата или роль. Ничего не менять — тоже выбор, и у него есть цена.'],
  whyRu:'За один год поменялись и правила, и рынок. Три штата приняли законы об AI-терапии в 2025 году, а договор штатов из закона стал работающим. Проверяйте раз в год — и ничто не застанет вас врасплох.',
  links:[{t:'Illinois IDFPR — AI therapy law release (official)', u:'https://idfpr.illinois.gov/news/2025/gov-pritzker-signs-state-leg-prohibiting-ai-therapy-in-il.html'},
         {t:'Arizona Board — Counseling Compact page (official)', u:'https://bbhe.az.gov/counseling-compact'}]}
});
